        public static ProfileState CopyReplacingCurrent(ProfileState value,CombatState current)
        {
            if(value==null)return null;
            var result=new ProfileState
            {
                activeMode=value.activeMode,
                baseCombatConfigHash=value.baseCombatConfigHash,
                bindingRevision=value.bindingRevision,
                challenge=CopyReplacingMode(value.challenge,value.activeMode==ProfileModeKind.Challenge,current),
                configHash=value.configHash,
                contentVersion=value.contentVersion,
                focusScale=value.focusScale,
                meta=Copy(value.meta),
                migrationPolicy=value.migrationPolicy,
                migrationSourceDigest=value.migrationSourceDigest,
                modeSequence=value.modeSequence,
                profileId=value.profileId,
                profileInstanceId=value.profileInstanceId,
                receipts=Copy(value.receipts),
                revision=value.revision,
                schemaVersion=value.schemaVersion,
                seed=value.seed,
                story=CopyReplacingMode(value.story,value.activeMode==ProfileModeKind.Story,current),
            };
            return result;
        }
        static ModeState CopyReplacingMode(ModeState value,bool active,CombatState current)
        {
            if(!active)return Copy(value);
            if(value==null)return null;
            var result=new ModeState
            {
                abilities=Copy(value.abilities),
                activeEncounterId=value.activeEncounterId,
                activeEventId=value.activeEventId,
                build=Copy(value.build),
                claimedRewardIds=Copy(value.claimedRewardIds),
                currentRoomId=value.currentRoomId,
                departureAbilitySnapshot=Copy(value.departureAbilitySnapshot),
                departureP5Rules=Copy(value.departureP5Rules),
                departureP5RulesHash=value.departureP5RulesHash,
                departurePreparation=Copy(value.departurePreparation),
                departureTraining=value.departureTraining,
                departureUnlockPoolSnapshot=Copy(value.departureUnlockPoolSnapshot),
                elapsedRealSeconds=value.elapsedRealSeconds,
                encounters=CopyReplacingEncounters(value.encounters,value.activeEncounterId,current),
                environmentFacts=Copy(value.environmentFacts),
                events=Copy(value.events),
                explicitPauseSeconds=value.explicitPauseSeconds,
                explorationCombat=string.IsNullOrEmpty(value.activeEncounterId)?Copy(current):Copy(value.explorationCombat),
                flags=Copy(value.flags),
                focusLostSeconds=value.focusLostSeconds,
                id=value.id,
                kind=value.kind,
                openedGateIds=Copy(value.openedGateIds),
                p6Departure=Copy(value.p6Departure),
                pendingReward=Copy(value.pendingReward),
                planHash=value.planHash,
                random=Copy(value.random),
                rooms=Copy(value.rooms),
                runEarnings=value.runEarnings,
                seed=value.seed,
                stage=value.stage,
                usedRestIds=Copy(value.usedRestIds),
                v11Build=Copy(value.v11Build),
                v11Departure=Copy(value.v11Departure),
                v12Run=Copy(value.v12Run),
            };
            return result;
        }
        static List<EncounterRecord> CopyReplacingEncounters(List<EncounterRecord> values,string activeId,CombatState current)
        {
            if(values==null)return null;
            var result=new List<EncounterRecord>(values.Count);
            foreach(var value in values)
            {
                if(value==null||value.id!=activeId){result.Add(Copy(value));continue;}
                result.Add(new EncounterRecord
                {
                    attemptId=value.attemptId,
                    attemptNumber=value.attemptNumber,
                    chargeCap=value.chargeCap,
                    configHash=value.configHash,
                    currentCombat=Copy(current),
                    encounterStartSnapshot=Copy(value.encounterStartSnapshot),
                    id=value.id,
                    initialCharge=value.initialCharge,
                    resolvedConfig=Copy(value.resolvedConfig),
                    roomId=value.roomId,
                    seed=value.seed,
                    stage=value.stage,
                });
            }
            return result;
        }
    }
}
